(function(){
function css(){if(document.getElementById('fpon-econ-chart-css'))return;const s=document.createElement('style');s.id='fpon-econ-chart-css';s.textContent='.econ .ec{position:relative}.econ-week{margin-top:14px;padding-top:12px;border-top:1px solid #e8edf3}.econ-week-head{display:flex;justify-content:space-between;align-items:center;gap:8px;margin-bottom:8px}.econ-week-head b{font-size:12px;color:#40556e}.econ-week-head span{font-size:10px;color:#8290a0}.econ-chart{width:100%;height:100px;display:block;overflow:visible}.econ-chart .grid{stroke:#e8edf3;stroke-width:1}.econ-chart .line{fill:none;stroke:#2f6fb0;stroke-width:2.5;stroke-linecap:round;stroke-linejoin:round}.econ-chart .dot{fill:#fff;stroke:#2f6fb0;stroke-width:2}.econ-chart text{font-size:9px;fill:#7a8795}.econ-chart .value{font-size:9px;font-weight:800;fill:#40556e}.econ-subcharts{display:grid;grid-template-columns:1fr 1fr;gap:10px}.econ-mini{min-width:0}.econ-mini-title{font-size:11px;font-weight:900;color:#40556e;margin-bottom:4px}@media(max-width:650px){.econ-subcharts{grid-template-columns:1fr}}';document.head.appendChild(s)}
const data={kospi:{name:'코스피',labels:['8/24','8/25','8/26','8/27','8/28','9/1'],values:[6696.96,6742.74,6808.21,6912.37,6788.88,6767.50]},kosdaq:{name:'코스닥',labels:['8/24','8/25','8/26','8/27','8/28','9/1'],values:[813.33,827.15,826.87,837.65,838.41,824.37]},usd:{name:'원/달러',labels:['8/24','8/25','8/26','8/27','8/28','9/1'],values:[1383.19,1382.58,1385.16,1381.76,1377.32,1368.78]},jpy:{name:'100엔/원',labels:['8/24','8/25','8/26','8/27','8/28','9/1'],values:[869.36,868.56,869.50,866.88,860.47,856.59]}};
function chart(o){const w=330,h=100,p={l:9,r:9,t:19,b:20},min=Math.min(...o.values),max=Math.max(...o.values),range=(max-min)||1,pts=o.values.map((v,i)=>{const x=p.l+i*(w-p.l-p.r)/(o.values.length-1),y=p.t+(max-v)/range*(h-p.t-p.b);return{x,y,v,label:o.labels[i]}});return '<svg class="econ-chart" viewBox="0 0 '+w+' '+h+'" preserveAspectRatio="none" aria-label="'+o.name+' 최근 1주일 추이"><line class="grid" x1="'+p.l+'" y1="'+(h-p.b)+'" x2="'+(w-p.r)+'" y2="'+(h-p.b)+'"/><polyline class="line" points="'+pts.map(q=>q.x+','+q.y).join(' ')+'"/>'+pts.map((q,i)=>'<circle class="dot" cx="'+q.x+'" cy="'+q.y+'" r="3"/><text x="'+q.x+'" y="'+(h-5)+'" text-anchor="middle">'+q.label+'</text>'+(i===pts.length-1?'<text class="value" x="'+(q.x-2)+'" y="'+Math.max(10,q.y-7)+'" text-anchor="end">'+q.v.toLocaleString('ko-KR',{maximumFractionDigits:2})+'</text>':'')).join('')+'</svg>'}
function block(title,items,note){return '<div class="econ-week"><div class="econ-week-head"><b>'+title+'</b><span>'+note+'</span></div>'+(items.length>1?'<div class="econ-subcharts">'+items.map(o=>'<div class="econ-mini"><div class="econ-mini-title">'+o.name+'</div>'+chart(o)+'</div>').join('')+'</div>':chart(items[0]))+'</div>'}
function init(){css();const stocks=document.querySelector('.ec.stocks'),fx=document.querySelector('.ec.fx');if(stocks){stocks.querySelectorAll('.econ-week').forEach(x=>x.remove());stocks.insertAdjacentHTML('beforeend',block('최근 1주일 지수 흐름',[data.kospi,data.kosdaq],'거래일 종가 기준'))}if(fx){fx.querySelectorAll('.econ-week').forEach(x=>x.remove());fx.insertAdjacentHTML('beforeend',block('최근 1주일 환율 흐름',[data.usd,data.jpy],'9/1 최신값 포함'))}}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',()=>setTimeout(init,1000));else setTimeout(init,1000);
})();